// ui_component_card.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_component_card

async function ui_component_card (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  // Extract '_' (sender) to fire events up
  const { io, _ } = net(id)

  io.on = {
    up: onmessage
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-card">
      <div class="card-preview"></div>

      <div class="card-footer">
        <div class="card-title">Radio button</div>

        <div class="card-bookmark">
          <span class="bookmark-icon"></span>
          <span class="bookmark-count">100</span>
        </div>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const card = shadow.querySelector('.ui-card')
  const bookmark_icon = shadow.querySelector('.bookmark-icon')

  await sdb.watch(onbatch)

  if (invite) io.accept(invite)

  // Trigger event upward on click
  card.onclick = () => {
    _.up('card_clicked', { sid: opts.sid })
  }

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    const [svg = ''] = data 
    bookmark_icon.innerHTML = svg 
  }

  function onmessage (msg) {
    console.log('ui_component_card:', msg.type)
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: {
          0: ''
        }
      },

      drive: {
        'icons/': {
          'bookmark.svg': { $ref: 'bookmark.svg' }
        },

        'style/ui_component_card.css': {
          $ref: 'ui_component_card.css'
        }
      }
    }
  }
}